fn contains_consecutive_numbers(a: &Vec<i32>) -> bool {
    if a.len() < 2 {
        return false;
    }

    for i in 0..(a.len() - 1) {
        // Use checked_add to avoid overflow when a[i] == i32::MAX
        if a[i].checked_add(1) == Some(a[i + 1]) {
            return true;
        }
    }

    false
}